@push('scripts')<script>
let suggestionsEtapes=[];
document.getElementById('suggerer-etapes-ia').addEventListener('click',async function(){const out=document.getElementById('etapes-ia-feedback');this.disabled=true;out.textContent='Analyse en cours…';try{const response=await fetch('{{ route('admin.plans-urgence.ia') }}',{method:'POST',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({action:'etapes_manquantes',plan_id:{{ $plan->id }}})});const data=await response.json();if(!response.ok)throw new Error(data.message||Object.values(data.errors||{}).flat().join(' '));suggestionsEtapes=data.etapes;const list=document.getElementById('etapes-ia-resultat');list.replaceChildren();data.etapes.forEach((item,i)=>{const row=document.createElement('div');row.className='form-check border rounded p-3 mb-2';const check=document.createElement('input');check.type='checkbox';check.className='form-check-input';check.checked=true;check.id=`etape-suggeree-${i}`;const label=document.createElement('label');label.className='form-check-label';label.htmlFor=check.id;label.textContent=`${item.titre} — ${item.moment}`;row.append(check,label);list.append(row);});document.getElementById('ajouter-etapes-ia').classList.toggle('d-none',!data.etapes.length);out.textContent=data.etapes.length?'Choisissez les suggestions à ajouter.':'Aucune étape manquante suggérée.';}catch(e){out.textContent=e.message;}finally{this.disabled=false;}});
document.getElementById('ajouter-etapes-ia').addEventListener('click',async function(){const checks=[...document.querySelectorAll('#etapes-ia-resultat input[type=checkbox]')];const selected=suggestionsEtapes.filter((_,i)=>checks[i].checked);if(!selected.length){document.getElementById('etapes-ia-feedback').textContent='Cochez au moins une étape.';return;}this.disabled=true;try{for(const item of selected){const response=await fetch('{{ route('admin.plans-urgence.etapes.store',$plan) }}',{method:'POST',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({titre:item.titre,description:item.description||'',moment:item.moment,obligatoire:item.obligatoire?1:0})});if(!response.ok)throw new Error('Une étape n’a pas pu être enregistrée.');}location.reload();}catch(e){document.getElementById('etapes-ia-feedback').textContent=e.message;}finally{this.disabled=false;}});
</script>@endpush
@endsection
